#!/bin/sh
# MainFrame updater for Linux - generated by vexelray-installer. Do not edit by hand; regenerate it.
#
#   update.sh           install the latest version, after asking
#   update.sh --check   only say whether there is one
#   update.sh --yes     do not ask
#
# Compares the installed version with the latest in the manifest, then runs that version's install.sh,
# accepted only when its SHA-256 matches the manifest, into the same folder with the same choices.

# shellcheck disable=SC2034
{
VI_ID='mainframe'
VI_NAME='MainFrame'
VI_PUBLISHER='sibarum'
VI_DESCRIPTION='A terminal window that wraps the native Windows shell over ConPTY, built on the VexelRay stack.'
VI_MANIFEST_URL='https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/mainframe/manifest.linux.txt'
VI_REGISTRY_DIR='$XDG_DATA_HOME/vexelray-installer/installs'
VI_ISSUES_URL='https://github.com/sibarum/vexelray-dist/issues/new'
}

set -u
vi_tab=$(printf '\t')

vi_say() { printf '%s\n' "$*"; }
vi_die() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }

vi_expand() {
    printf '%s\n' "$1" | awk '{
        s = $0; out = ""
        if (s == "~" || substr(s, 1, 2) == "~/") { out = ENVIRON["HOME"]; s = substr(s, 2) }
        while (match(s, /\$\{[A-Za-z_][A-Za-z0-9_]*\}|\$[A-Za-z_][A-Za-z0-9_]*/)) {
            v = substr(s, RSTART, RLENGTH); gsub(/[${}]/, "", v)
            out = out substr(s, 1, RSTART - 1) ENVIRON[v]; s = substr(s, RSTART + RLENGTH)
        }
        print out s }'
}

vi_sha() {
    if command -v sha256sum >/dev/null 2>&1; then sha256sum < "$1" | cut -d' ' -f1
    else shasum -a 256 < "$1" | cut -d' ' -f1; fi
}

vi_get() {
    if command -v curl >/dev/null 2>&1; then curl -fsSL --retry 3 --connect-timeout 30 -o "$2" "$1"
    else wget -q --tries=3 -O "$2" "$1"; fi
}

vi_cmp() {
    awk -v a="$1" -v b="$2" '
        function key(v, k,   c, n, i, p) {
            sub(/^[vV]/, "", v); c = v; sub(/[-+].*$/, "", c); n = split(c, p, ".")
            for (i = 1; i <= 4; i++) k[i] = (i <= n ? p[i] + 0 : 0)
            return index(v, "-") > 0
        }
        BEGIN {
            pa = key(a, x); pb = key(b, y)
            for (i = 1; i <= 4; i++) { if (x[i] < y[i]) { print -1; exit } if (x[i] > y[i]) { print 1; exit } }
            print (pa && !pb) ? -1 : (!pa && pb) ? 1 : 0
        }'
}

vi_state() { awk -F'\t' -v k="$2" '$1 == k { print $2; exit }' "$1" 2>/dev/null; }

vi_main() {
    vi_check=0; vi_yes=0
    while [ $# -gt 0 ]; do
        case $1 in
            --check|-Check) vi_check=1 ;;
            --yes|-Yes|-y) vi_yes=1 ;;
            *) printf 'Warning: Ignoring unknown argument: %s\n' "$1" >&2 ;;
        esac
        shift
    done
    [ -n "${HOME:-}" ] || vi_die "HOME is not set."
    export XDG_DATA_HOME="${XDG_DATA_HOME:-$HOME/.local/share}"
    vi_reg=${INSTALL_REGISTRY_DIR:-}
    [ -n "$vi_reg" ] || vi_reg=$(vi_expand "$VI_REGISTRY_DIR")
    vi_rec="$vi_reg/$VI_ID.state"
    [ -f "$vi_rec" ] || vi_die "$VI_NAME is not installed (no record in $vi_reg)."
    vi_cur=$(vi_state "$vi_rec" version)
    vi_dir=$(vi_state "$vi_rec" installDir)

    vi_tmp=$(mktemp -d "${TMPDIR:-/tmp}/vi-update.XXXXXX") || vi_die "Cannot create a temporary folder."
    trap 'rm -rf -- "$vi_tmp"' EXIT
    trap 'exit 1' INT TERM HUP
    vi_mf="$vi_tmp/manifest.txt"
    vi_get "$VI_MANIFEST_URL" "$vi_mf" || vi_die "Could not download $VI_MANIFEST_URL."
    [ "$(head -n 1 "$vi_mf")" = "vexelray-installer-linux${vi_tab}1" ] || vi_die "$VI_MANIFEST_URL is not a manifest this updater reads."
    vi_latest=$(awk -F'\t' '$1 == "latest" { print $2; exit }' "$vi_mf")
    [ -n "$vi_latest" ] && [ "$vi_latest" != - ] || vi_die "The manifest names no Linux version."

    if [ "$(vi_cmp "$vi_latest" "$vi_cur")" -le 0 ]; then
        vi_say "$VI_NAME $vi_cur is up to date."
        return 0
    fi
    vi_say "$VI_NAME $vi_latest is available (installed: $vi_cur)."
    [ "$vi_check" = 1 ] && return 0
    if [ "$vi_yes" = 0 ]; then
        (: < /dev/tty) 2>/dev/null || vi_die "Nothing to ask with; run it with --yes to update."
        printf 'Update to %s? [y/N] ' "$vi_latest" > /dev/tty
        read -r vi_answer < /dev/tty || vi_answer=
        case $vi_answer in y|Y|yes|Yes|YES) ;; *) vi_say "Not updated."; return 0 ;; esac
    fi

    vi_t=$(awk -F'\t' '$1 == "tool" && $2 == "install.sh"' "$vi_mf")
    [ -n "$vi_t" ] || vi_die "The manifest names no install.sh."
    IFS="$vi_tab" read -r _ _ vi_tsha vi_turl <<EOF
$vi_t
EOF
    vi_get "$vi_turl" "$vi_tmp/install.sh" || vi_die "Could not download $vi_turl."
    [ "$(vi_sha "$vi_tmp/install.sh")" = "$vi_tsha" ] || vi_die "install.sh does not match the SHA-256 in the manifest; nothing was changed."
    INSTALL_VERSION='' INSTALL_FORCE='' INSTALL_DIR="$vi_dir" sh "$vi_tmp/install.sh"
}

vi_main "$@"
